class Solution {
    fun findOriginalArray(changed:IntArray):IntArray{
        if(changed.size%2==1)return intArrayOf();
        changed.sort();
        val frequency=HashMap<Int,Int>();
        for(value in changed)frequency[value]=(frequency[value]?:0)+1;
        val answer=IntArray(changed.size/2);
        var index=0;
        for(value in changed)if((frequency[value]?:0)>0){
            if((frequency[value*2]?:0)==0)return intArrayOf();
            frequency[value]=frequency[value]!!-1;
            frequency[value*2]=frequency[value*2]!!-1;
            answer[index++]=value
        };
        return answer
    }
}

